#include <iostream>

int main()
{
    int total{0};

    for (int step{1}; step <= 3; ++step) {
        std::cout << "Step " << step << "\n";
        total += step;
    }

    std::cout << "Total: " << total << "\n";
}

#include <iostream>

int main()
{
    int remaining{3};

    while (remaining > 0) {
        std::cout << remaining << "\n";
        --remaining;
    }

    std::cout << "Go!\n";
}
